-- Blind test batches; schema is also generated by SQLAlchemy Base.metadata.create_all.
CREATE TABLE IF NOT EXISTS blind_batches(id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,title VARCHAR(120) NOT NULL,lot VARCHAR(60) NOT NULL,status VARCHAR(20) NOT NULL,assessment_id INTEGER UNIQUE REFERENCES assessments(id),created_by VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL,sealed_at VARCHAR(40) NOT NULL,unblinded_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS blind_items(id SERIAL PRIMARY KEY,batch_id INTEGER NOT NULL REFERENCES blind_batches(id),blind_code VARCHAR(50) UNIQUE NOT NULL,group_alias VARCHAR(10) NOT NULL,process_id INTEGER NOT NULL REFERENCES processes(id),returned_force FLOAT,returned_at VARCHAR(40) NOT NULL,returned_by VARCHAR(120) NOT NULL,sample_id INTEGER UNIQUE REFERENCES samples(id));
